    1: [(0,4,8), (10,10,5)],  # Position changed: moved up
    2: [(0,10,8), (10,0,5)],  # Swapped! big shape moved, small shape moved
    5: [(3,2,10)],  # Moved up from row 8 to row 3
    8: [(10,6,6)]   # Moved down from row 5 to row 10
}

print("Sort order analysis (row, col):")
print("Input positions:")
for color in [1,2,5,8]:
    for tr, tc, sz in input_comps[color]:
        print(f"  {color}: ({tr}, {tc}) size={sz}")

print("\nOutput positions:")
for color in [1,2,5,8]:
    for tr, tc, sz in output_comps[color]:
        print(f"  {color}: ({tr}, {tc}) size={sz}")

# Sorting by (row, col) ascending
